"use client";

import { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth-context';
import { AuthShell } from '@/components/auth-shell';

export default function LoginPage() {
  const router = useRouter();
  const { signIn } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(true);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setLoading(true);
    const { error } = await signIn(email, password, rememberMe);
    setLoading(false);
    if (error) {
      setMessage(error.message);
      return;
    }
    router.push('/dashboard');
  };

  return (
    <AuthShell title="Welcome back" subtitle="Sign in to your account and resume your orders, wishlist, and preferences.">
      <form onSubmit={handleSubmit} className="grid gap-4 rounded-2xl border border-slate-800 bg-slate-950/70 p-6">
        <input type="email" value={email} onChange={(event) => setEmail(event.target.value)} className="rounded-xl border border-slate-700 bg-slate-900 px-4 py-3" placeholder="Email" required />
        <input type="password" value={password} onChange={(event) => setPassword(event.target.value)} className="rounded-xl border border-slate-700 bg-slate-900 px-4 py-3" placeholder="Password" required />
        <label className="flex items-center gap-2 text-sm text-slate-400">
          <input type="checkbox" checked={rememberMe} onChange={(event) => setRememberMe(event.target.checked)} />
          Remember me
        </label>
        <button disabled={loading} className="rounded-xl bg-cyan-500 px-4 py-3 font-medium text-slate-950 transition hover:bg-cyan-400 disabled:opacity-70">
          {loading ? 'Signing in…' : 'Sign in'}
        </button>
        {message ? <p className="text-sm text-slate-300">{message}</p> : null}
        <div className="flex items-center justify-between text-sm">
          <Link href="/auth/forgot-password" className="text-cyan-300">Forgot password?</Link>
          <Link href="/auth/register" className="text-cyan-300">Create account</Link>
        </div>
      </form>
    </AuthShell>
  );
}
